-- Feed/Forage taxonomy unification: feed is the umbrella term (forage, concentrate, mineral,
-- vitamin, additive are all classes of feed), replacing the old ForageType/FeedIngredientCategory
-- enums which named forage as a category separate from feed. Also links Forage (renamed FeedItem
-- at the Prisma-model level via @@map, zero SQL impact) to FeedIngredient by a real FK, replacing
-- the lowercased-name match the app previously relied on.
--
-- Hand-authored (not autogenerated) because it drops enum values with existing data — additive
-- steps run non-interactively via `migrate dev`, but a value-dropping migration needs this
-- expand -> backfill -> contract shape applied via `migrate deploy` per repo convention.

-- CreateEnum
CREATE TYPE "FeedClass" AS ENUM ('FORAGE', 'CONCENTRATE', 'MINERAL', 'VITAMIN', 'ADDITIVE', 'OTHER');

-- CreateEnum
CREATE TYPE "FeedSubType" AS ENUM ('GREEN_FODDER', 'ROUGHAGE', 'SILAGE', 'HAY', 'STRAW', 'GRAIN', 'OILCAKE', 'BY_PRODUCT', 'COMPOUND_PELLET', 'PREMIX', 'SUPPLEMENT', 'OTHER');

-- ==== Forage ================================================================================

-- AlterTable: add nullable first, backfill existing rows, then enforce NOT NULL (feedClass only;
-- feedSubType stays optional per schema).
ALTER TABLE "Forage" ADD COLUMN     "feedClass" "FeedClass",
ADD COLUMN     "feedSubType" "FeedSubType",
ADD COLUMN     "ingredientId" TEXT;

-- Lossless backfill from the old 7-value ForageType (every value maps to exactly one
-- FeedClass/FeedSubType pair — see the ticket's mapping table).
UPDATE "Forage"
SET "feedClass" = CASE "type"
  WHEN 'ROUGHAGE' THEN 'FORAGE'
  WHEN 'SILAGE' THEN 'FORAGE'
  WHEN 'CONCENTRATE' THEN 'CONCENTRATE'
  WHEN 'BY_PRODUCT' THEN 'CONCENTRATE'
  WHEN 'SUPPLEMENT' THEN 'ADDITIVE'
  WHEN 'MINERAL' THEN 'MINERAL'
  WHEN 'OTHER' THEN 'OTHER'
END::"FeedClass",
"feedSubType" = CASE "type"
  WHEN 'ROUGHAGE' THEN 'ROUGHAGE'
  WHEN 'SILAGE' THEN 'SILAGE'
  WHEN 'CONCENTRATE' THEN 'GRAIN'
  WHEN 'BY_PRODUCT' THEN 'BY_PRODUCT'
  WHEN 'SUPPLEMENT' THEN 'SUPPLEMENT'
  WHEN 'MINERAL' THEN 'PREMIX'
  WHEN 'OTHER' THEN 'OTHER'
END::"FeedSubType";

ALTER TABLE "Forage" ALTER COLUMN "feedClass" SET NOT NULL;

-- DropIndex
DROP INDEX "Forage_type_idx";

-- AlterTable: drop the now-superseded enum column.
ALTER TABLE "Forage" DROP COLUMN "type";

-- DropEnum
DROP TYPE "ForageType";

-- CreateIndex
CREATE INDEX "Forage_feedClass_idx" ON "Forage"("feedClass");

-- CreateIndex
CREATE INDEX "Forage_ingredientId_idx" ON "Forage"("ingredientId");

-- ==== FeedIngredient =========================================================================

-- AlterTable
ALTER TABLE "FeedIngredient" ADD COLUMN     "feedClass" "FeedClass",
ADD COLUMN     "feedSubType" "FeedSubType";

-- Lossless backfill from the old 5-value FeedIngredientCategory (a subset of ForageType's values,
-- same mapping).
UPDATE "FeedIngredient"
SET "feedClass" = CASE "category"
  WHEN 'ROUGHAGE' THEN 'FORAGE'
  WHEN 'SILAGE' THEN 'FORAGE'
  WHEN 'CONCENTRATE' THEN 'CONCENTRATE'
  WHEN 'BY_PRODUCT' THEN 'CONCENTRATE'
  WHEN 'SUPPLEMENT' THEN 'ADDITIVE'
END::"FeedClass",
"feedSubType" = CASE "category"
  WHEN 'ROUGHAGE' THEN 'ROUGHAGE'
  WHEN 'SILAGE' THEN 'SILAGE'
  WHEN 'CONCENTRATE' THEN 'GRAIN'
  WHEN 'BY_PRODUCT' THEN 'BY_PRODUCT'
  WHEN 'SUPPLEMENT' THEN 'SUPPLEMENT'
END::"FeedSubType";

ALTER TABLE "FeedIngredient" ALTER COLUMN "feedClass" SET NOT NULL;

-- DropIndex
DROP INDEX "FeedIngredient_category_idx";

-- AlterTable
ALTER TABLE "FeedIngredient" DROP COLUMN "category";

-- DropEnum
DROP TYPE "FeedIngredientCategory";

-- CreateIndex
CREATE INDEX "FeedIngredient_feedClass_idx" ON "FeedIngredient"("feedClass");

-- ==== FK: Forage.ingredientId -> FeedIngredient.id ==========================================

-- AddForeignKey
ALTER TABLE "Forage" ADD CONSTRAINT "Forage_ingredientId_fkey" FOREIGN KEY ("ingredientId") REFERENCES "FeedIngredient"("id") ON DELETE SET NULL ON UPDATE CASCADE;
